#include <iostream>
#include <vector>

int main() {
    std::vector<int> luvut = {1, 2, 3};
    for (int luku : luvut) {
        luku *= 10;
    }
    for (int& luku : luvut) {
        luku *= 2;
    }
    for (int luku : luvut) {
        std::cout << luku << " ";
    }
    std::cout << "\n";
    return 0;
}

